						if err := decoder.Decode(&response); err != nil {
							return err
						}
						if len(response.Items) != 1 || response.Items[0].Claims["repository_id"] != json.Number("9007199254740993") {
							return fmt.Errorf("rule list did not preserve full claims: %s", raw)
						}
