func TestWorkspaceWIFIncompleteCreateKeepsIdentityForCleanup(t *testing.T) {
	f := newWorkspaceWIFFixture()
	f.failBinding = true
	s := f.server(t)
	server, schemas := workspaceWIFProtocol(t, s.URL)
	typ := schemas.ResourceSchemas[workspaceWIFProviderType].ValueType()
	config := workspaceWIFValue(t, typ, map[string]any{"workspace_id": workspaceWIFID, "name": "CI", "issuer": "https://issuer.example.com"})
	null := workspaceWIFValue(t, typ, nil)
	ctx := context.Background()
	plan, err := server.PlanResourceChange(ctx, &tfprotov6.PlanResourceChangeRequest{TypeName: workspaceWIFProviderType, PriorState: null, Config: config, ProposedNewState: config})
	if err != nil {
		t.Fatal(err)
	}
	workspaceWIFNoErrors(t, plan.Diagnostics)
	created, err := server.ApplyResourceChange(ctx, &tfprotov6.ApplyResourceChangeRequest{TypeName: workspaceWIFProviderType, PriorState: null, PlannedState: plan.PlannedState, Config: config})
	if err != nil {
		t.Fatal(err)
	}
	if !workspaceWIFHasError(created.Diagnostics) {
		t.Fatal("binding failure did not fail creation")
	}
	value, err := created.NewState.Unmarshal(typ)
	if err != nil {
		t.Fatal(err)
	}
	var fields map[string]tftypes.Value
	if err := value.As(&fields); err != nil {
		t.Fatal(err)
	}
	var id string
	if err := fields["id"].As(&id); err != nil || id != "wip_synthetic" {
		t.Fatalf("lost created identity: %s, %v", id, err)
	}
	read, err := server.ReadResource(ctx, &tfprotov6.ReadResourceRequest{TypeName: workspaceWIFProviderType, CurrentState: created.NewState, Private: created.Private})
	if err != nil {
		t.Fatal(err)
	}
	workspaceWIFNoErrors(t, read.Diagnostics)
	retained, err := read.NewState.Unmarshal(typ)
	if err != nil || retained.IsNull() {
		t.Fatalf("refresh forgot an unattached provider: %v", err)
	}
	f.mu.Lock()
	if f.writes["POST "+workspaceWIFCollection] != 1 || f.writes["POST "+workspaceWIFProviderPath+"/bindings"] != 1 {
		t.Error("failed create was retried")
	}
	f.failBinding = false
	f.mu.Unlock()
	destroyed, err := server.ApplyResourceChange(ctx, &tfprotov6.ApplyResourceChangeRequest{TypeName: workspaceWIFProviderType, PriorState: read.NewState, PlannedState: null, Config: null, PlannedPrivate: read.Private})
	if err != nil {
		t.Fatal(err)
	}
	workspaceWIFNoErrors(t, destroyed.Diagnostics)
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.provider != nil {
		t.Fatal("incomplete provider was orphaned")
	}
}

func TestWorkspaceWIFReadErrorsAndDeleteOwnership(t *testing.T) {
	for _, typeName := range []string{workspaceWIFProviderType, workspaceWIFRuleType} {
		t.Run(typeName, func(t *testing.T) {
			f := newWorkspaceWIFFixture()
			f.seed()
			s := f.server(t)
			server, schemas := workspaceWIFProtocol(t, s.URL)
			state := workspaceWIFImported(t, server, typeName)
			typ := schemas.ResourceSchemas[typeName].ValueType()
			readPath, missingCode := workspaceWIFProviderPath, "workload_identity_provider_not_found"
			if typeName == workspaceWIFRuleType {
				readPath, missingCode = workspaceWIFRulePath, "workload_identity_mapping_not_found"
			}
			for _, scenario := range []struct {
				status int
				code   string
				absent bool
			}{
				{400, missingCode, true}, {400, "invalid_request", false}, {403, missingCode, false}, {404, "not_found", false},
			} {
				f.mu.Lock()
				f.readPath, f.readStatus, f.readCode = readPath, scenario.status, scenario.code
				f.mu.Unlock()
				read, err := server.ReadResource(context.Background(), &tfprotov6.ReadResourceRequest{TypeName: typeName, CurrentState: state})
				if err != nil {
					t.Fatal(err)
				}
				value, err := read.NewState.Unmarshal(typ)
				if err != nil {
					t.Fatal(err)
				}
				if value.IsNull() != scenario.absent || workspaceWIFHasError(read.Diagnostics) == scenario.absent {
					t.Fatalf("incorrect absence handling for %d/%s: %v", scenario.status, scenario.code, read.Diagnostics)
				}
			}
			f.mu.Lock()
			f.readPath = ""
			f.provider["owner_type"], f.provider["owner_id"] = "tenant", "tenant_synthetic"
			f.mu.Unlock()
			null := workspaceWIFValue(t, typ, nil)
			destroyed, err := server.ApplyResourceChange(context.Background(), &tfprotov6.ApplyResourceChangeRequest{TypeName: typeName, PriorState: state, PlannedState: null, Config: null})
			if err != nil {
				t.Fatal(err)
			}
			if !workspaceWIFHasError(destroyed.Diagnostics) {
				t.Fatal("resource tried to manage a tenant-owned provider")
			}
			f.mu.Lock()
			defer f.mu.Unlock()
			if len(f.writes) != 0 {
				t.Fatalf("ownership failure performed a mutation: %v", f.writes)
			}
		})
	}
}
